package com.mulino.application.work;

import com.mulino.application.core.*;
import com.mulino.domain.work.*;
import com.mulino.domain.definitions.DefinitionRepository;
import com.mulino.domain.identity.IdentityRepository;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.stereotype.Component;

@Component
public class WorkLifecycle implements CommandHandler,WorkFollowup {
 private final WorkRepository repository; private final IdentityRepository identities; private final DefinitionRepository definitions; private final com.mulino.domain.governance.PolicyRepository policies;
 private final ObjectProvider<WorkAssessmentGuard> assessments; private final ObjectProvider<WorkResponsibility> responsibility;
 private final ObjectMapper json=new ObjectMapper(); private final ExecutionClock clock;
 public WorkLifecycle(WorkRepository repository,IdentityRepository identities,DefinitionRepository definitions,com.mulino.domain.governance.PolicyRepository policies,ObjectProvider<WorkAssessmentGuard> assessments,ObjectProvider<WorkResponsibility> responsibility,ExecutionClock clock){this.repository=repository;this.identities=identities;this.definitions=definitions;this.policies=policies;this.assessments=assessments;this.responsibility=responsibility;this.clock=clock;}
 public Set<String> capabilities(){return Set.of("createWork","createDraft","cancelDraft","activateWork","waitWork","resumeWork","reviseGoal","closeWork","createFollowup","createWorkLink");}
 public Set<String> definitionVersions(){return Set.of("1.0.0","definition-v1");}
 public List<SubjectBinding> subjectBindings(DomainContext c,Map<String,Object> intent,CommandPreparation preparation){
  var p=parameters(c,intent);String op=operation(intent);
  if(op.equals("createDraft")||op.equals("createWork")){var items=Set.of(id(p,"itemId"));return List.of(map(intent.get("slots")).containsKey("goal")?SubjectBinding.optional("TradeItem",items):SubjectBinding.required("TradeItem",items));}
  String source=id(p,"workId");var targets=new HashSet<String>(Set.of(source));var items=new HashSet<String>(Set.of(String.valueOf(repository.require(c,source,false).get("itemId"))));
  if(op.equals("createWorkLink")){String target=id(p,"targetWorkId");targets.add(target);items.add(String.valueOf(repository.require(c,target,false).get("itemId")));}
  if(op.equals("createFollowup"))items.add(id(map(p.get("draft")),"itemId"));
  return List.of(SubjectBinding.optional("Work",targets),SubjectBinding.optional("TradeItem",items));
 }
 public CommandPreparation prepare(DomainContext c,Map<String,Object> intent){var p=parameters(c,intent);String op=operation(intent);validateKeys(op,p);if((op.equals("createDraft")||op.equals("createWork"))&&intent.containsKey("definitionVersion")){var pinned=definitions.get(c.organizationId(),id(p,"definitionVersionId"));if(!Objects.equals(pinned.version(),intent.get("definitionVersion"))&&!Objects.equals(pinned.id(),intent.get("definitionVersion")))throw DomainError.unsupported();}if(p.get("goal") instanceof Map<?,?>)GoalInput.validate(map(p.get("goal")),false);
  if(op.equals("createDraft")||op.equals("createWork")){String item=id(p,"itemId");return new CommandPreparation(Map.of("ITEM",List.of(item)),List.of("work-create:"+item),new HashSet<>(List.of(id(p,"ownerId"),id(p,"supervisorId"))),"WORK",null,null,0,null,null);}
  String id=id(p,"workId");var w=repository.require(c,id,false);var works=new ArrayList<String>(List.of(id));var items=new ArrayList<String>(List.of(String.valueOf(w.get("itemId"))));var fences=new ArrayList<String>(List.of("work:"+id));var actors=new HashSet<String>(List.of(String.valueOf(w.get("ownerId")),String.valueOf(w.get("supervisorId"))));
  if(op.equals("createWorkLink")){String target=id(p,"targetWorkId");var targetWork=repository.require(c,target,false);works.add(target);items.add(String.valueOf(targetWork.get("itemId")));fences.add("work:"+target);fences.add("work-graph:"+c.organizationId());if(p.containsKey("occurrenceId")){var actual=repository.occurrence(c,id(p,"occurrenceId"));items.add(String.valueOf(actual.get("itemId")));fences.add("contribution:"+p.get("occurrenceId"));}}
  if(op.equals("createFollowup")){var draft=map(p.get("draft"));validateKeys("createDraft",draft);items.add(id(draft,"itemId"));actors.add(id(draft,"ownerId"));actors.add(id(draft,"supervisorId"));}
  return new CommandPreparation(Map.of("WORK",works,"TARGET",works,"ITEM",items),fences,actors,"WORK",null,null,0,id,((Number)w.get("revision")).intValue());
 }
 public Map<String,Object> execute(DomainContext c,Map<String,Object> intent){var p=parameters(c,intent);String op=operation(intent);if(op.equals("createDraft"))return create(c,p,null);if(op.equals("createWork")){GoalInput.validate(map(p.get("goal")),true);var created=create(c,p,null);String id=String.valueOf(((Map<?,?>)created.get("effects")).get("workId"));activateCreated(c,id);var assessment=guard().assessCreated(c,id);var current=repository.require(c,id,false);var response=new LinkedHashMap<String,Object>(result(id,String.valueOf(current.get("currentGoalVersionId")),((Number)current.get("revision")).intValue(),"APPLIED"));response.put("workId",id);response.put("id",id);response.put("assessment",assessment);return response;}
  String id=id(p,"workId");var w=repository.require(c,id,true);if(!Objects.equals(w.get("lifecycleMode"),"COMMAND"))throw new DomainError("NEEDS_INPUT","IMPORTED_WORK","Imported reference requires explicit lifecycle migration");
  int rev=((Number)w.get("revision")).intValue();if(!(intent.get("expectedRevision") instanceof Number n)||n.intValue()!=rev)throw new DomainError("CONFLICT","REVISION_CONFLICT","Work revision changed");
  String state=String.valueOf(w.get("status"));var changes=new LinkedHashMap<String,Object>();String goalId=String.valueOf(w.get("currentGoalVersionId"));
  switch(op){
   case "cancelDraft"->{state(state,"DRAFT");duties().requireSettled(c,id);changes.put("status","CLOSED");changes.put("closeReason","CANCELLED");GoalInput.text(p,"reason");}
   case "activateWork"->{state(state,"DRAFT");var goal=repository.currentGoal(c,id);var slots=decode(goal.get("slotsJson"));GoalInput.validate(slots,true);guard().requireSupportedGoal(c,goal);human(c,String.valueOf(w.get("ownerId")));human(c,String.valueOf(w.get("supervisorId")));definitions.get(c.organizationId(),String.valueOf(w.get("definitionVersionId")));duties().activated(c,w,goal);changes.put("status","ACTIVE");}
   case "waitWork"->{state(state,"ACTIVE");var wait=map(p.get("wait"));if(!wait.keySet().equals(Set.of("reason","target","resumePredicate","verifier","nextCheckAt","overdueAction")))throw DomainError.invalid("Complete wait contract required");for(String key:List.of("reason","target","verifier","overdueAction"))GoalInput.text(wait,key);Instant.parse(GoalInput.text(wait,"nextCheckAt"));if(!(wait.get("resumePredicate") instanceof Map))throw DomainError.invalid("Typed resume predicate required");changes.put("waitJson",encode(wait));changes.put("status","WAITING");}
   case "resumeWork"->{state(state,"WAITING");guard().requireResume(c,w,decode(w.get("waitJson")),map(p.get("evidence")));changes.put("status","ACTIVE");changes.put("waitJson",null);}
   case "reviseGoal"->{if(!Set.of("DRAFT","ACTIVE","WAITING").contains(state))throw DomainError.invalid("Closed goal cannot change");GoalInput.text(p,"reason");var slots=map(p.get("goal"));GoalInput.validate(slots,!state.equals("DRAFT"));var old=repository.currentGoal(c,id);goalId=goal(c,w,slots,String.valueOf(old.get("ID")),((Number)old.get("goalVersion")).intValue()+1);if(!state.equals("DRAFT")){var pinned=new LinkedHashMap<String,Object>();pinned.put("definitionVersionId",w.get("definitionVersionId"));pinned.put("slotsJson",encode(slots));pinned.put("endpoint",slots.get("endpoint"));pinned.put("quantityMode",slots.get("quantityMode"));guard().requireSupportedGoal(c,pinned);}guard().goalChanged(c,id,String.valueOf(old.get("ID")),goalId);changes.put("currentGoalVersionId",goalId);changes.put("goalRevisionRequired",false);changes.put("pendingInvalidation",true);}
   case "closeWork"->{if(!Set.of("ACTIVE","WAITING").contains(state))throw DomainError.invalid("Only active/waiting work closes");String reason=GoalInput.text(p,"reason");if(!Set.of("FULFILLED","CANCELLED","IMPOSSIBLE","SUPERSEDED").contains(reason))throw DomainError.invalid("Invalid close reason");duties().requireSettled(c,id);if(reason.equals("FULFILLED")){if(Boolean.TRUE.equals(w.get("goalRevisionRequired")))throw new DomainError("NEEDS_INPUT","GOAL_REVISION_REQUIRED","Followup requires its own explicit goal revision");if(Boolean.TRUE.equals(w.get("pendingInvalidation")))throw new DomainError("HELD","ASSESSMENT_PENDING","Pending invalidation prevents fulfillment");guard().requireFulfilled(c,w,repository.currentGoal(c,id));}changes.put("status","CLOSED");changes.put("closeReason",reason);}
   case "createFollowup"->{state(state,"CLOSED");var result=create(c,map(p.get("draft")),id);String child=String.valueOf(((Map<?,?>)result.get("effects")).get("workId"));activateCreated(c,child);duties().followup(c,id,child,p);return result(child,String.valueOf(repository.require(c,child,false).get("currentGoalVersionId")),1,"APPLIED");}
   case "createWorkLink"->{String target=id(p,"targetWorkId");repository.require(c,target,true);String kind=GoalInput.text(p,"kind");if(!Set.of("CONTRIBUTES_TO","DEPENDS_ON","SHARES_ACTIVITY").contains(kind)||(id.equals(target)&&!kind.equals("SHARES_ACTIVITY")))throw DomainError.invalid("Invalid work link");if(kind.equals("DEPENDS_ON")&&reachable(c,target,id,new HashSet<>()))throw DomainError.invalid("Blocking dependency cycle");String link;if(p.containsKey("activityId")){var activity=repository.activity(c,id(p,"activityId"),id(p,"occurrenceId"));if(!Objects.equals(id,activity.get("workId")==null?target:activity.get("workId")))throw DomainError.invalid("Activity Work changed after command fencing");if(!Objects.equals(w.get("itemId"),activity.get("itemId")))throw DomainError.invalid("Activity item differs from Work");link=link(c,(String)activity.get("workId"),target,kind,id(p,"activityId"));}else link=link(c,id,target,kind);if(p.containsKey("occurrenceId")){repository.credit(c,link,target,p);if(id.equals(target)){var current=repository.require(c,id,false);rev=((Number)current.get("revision")).intValue();w=current;}}else if(kind.equals("CONTRIBUTES_TO"))throw new DomainError("NEEDS_INPUT","CONTRIBUTION_SCOPE_MISSING","Actual occurrence and disjoint credit range required");}
   default->throw DomainError.unsupported();
  }
  changes.put("revision",rev+1);changes.put("recordedAt",clock.instant());changes.put("effectiveAt",clock.instant());repository.update(c,id,changes);var snapshot=new LinkedHashMap<>(w);snapshot.putAll(changes);transition(c,snapshot,op,state,(String)p.get("reason"));return result(id,goalId,rev+1,"APPLIED");
 }
 public Map<String,Object> ensure(DomainContext c,String originalId,String sourceId,String reason,String nextAction,Instant nextCheckAt){
  if(sourceId==null||sourceId.isBlank()||reason==null||reason.isBlank()||nextAction==null||nextAction.isBlank()||nextCheckAt==null)throw DomainError.invalid("Current followup responsibility required");
  var original=repository.require(c,originalId,true);state(String.valueOf(original.get("status")),"CLOSED");String stable=UUID.nameUUIDFromBytes((c.organizationId()+"|"+originalId+"|"+sourceId).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();var existing=repository.find(c,stable);if(existing.isPresent())return existing.get();var p=new LinkedHashMap<String,Object>();p.put("itemId",original.get("itemId"));if(original.get("lotId")!=null)p.put("lotId",original.get("lotId"));p.put("definitionVersionId",original.get("definitionVersionId"));p.put("kind","FOLLOWUP");p.put("ownerId",original.get("ownerId"));p.put("supervisorId",original.get("supervisorId"));p.put("goal",decode(repository.currentGoal(c,originalId).get("slotsJson")));p.put("originalText",reason);p.put("conversationRequestId",sourceId);create(c,p,originalId,stable);activateCreated(c,stable);repository.update(c,stable,Map.of("goalRevisionRequired",true));repository.markInvalidation(c,stable,true);return repository.require(c,stable,false);
 }
 private Map<String,Object> create(DomainContext c,Map<String,Object> p,String original){return create(c,p,original,UUID.randomUUID().toString());}
 private Map<String,Object> create(DomainContext c,Map<String,Object> p,String original,String id){validateKeys("createDraft",p);String owner=id(p,"ownerId"),supervisor=id(p,"supervisorId");human(c,owner);human(c,supervisor);String definition=id(p,"definitionVersionId");definitions.get(c.organizationId(),definition);var w=row(c,id);w.put("itemId",id(p,"itemId"));if(p.containsKey("lotId"))w.put("lotId",id(p,"lotId"));w.put("definitionVersionId",definition);w.put("kind",GoalInput.text(p,"kind"));w.put("status","DRAFT");w.put("ownerId",owner);w.put("supervisorId",supervisor);w.put("lifecycleMode","COMMAND");w.put("pendingInvalidation",false);for(String key:List.of("originalText","conversationRequestId"))if(p.containsKey(key))w.put(key,p.get(key));repository.insert("mulino.work.read.Works",w);var slots=p.containsKey("goal")?map(p.get("goal")):Map.<String,Object>of();GoalInput.validate(slots,false);String goal=goal(c,w,slots,null,1);repository.update(c,id,Map.of("currentGoalVersionId",goal));w.put("currentGoalVersionId",goal);if(original!=null)link(c,original,id,"FOLLOWUP");transition(c,repository.require(c,id,false),"createDraft",null,null);return result(id,goal,0,"APPLIED");}
 private String goal(DomainContext c,Map<String,Object> work,Map<String,Object> slots,String previous,int version){String id=UUID.randomUUID().toString();var g=row(c,id);g.put("workId",work.get("ID"));g.put("definitionVersionId",work.get("definitionVersionId"));if(slots.containsKey("quantityMode"))g.put("quantityMode",slots.get("quantityMode"));g.put("scopeJson",encode(slots.getOrDefault("scope",Map.of())));g.put("slotsJson",encode(slots));g.put("provenanceJson",encode(slots.getOrDefault("provenance",Map.of())));g.put("goalVersion",version);if(previous!=null)g.put("previousGoalId",previous);for(String key:List.of("unit","endpoint","evidencePolicyVersion","timezone"))if(slots.containsKey(key))g.put(key,slots.get(key));if(slots.containsKey("targetQuantity"))g.put("targetQuantity",new java.math.BigDecimal(String.valueOf(slots.get("targetQuantity"))));if(slots.containsKey("dueAt"))g.put("dueAt",Instant.parse(String.valueOf(slots.get("dueAt"))));repository.insert("mulino.work.read.GoalReferences",g);return id;}
 private String link(DomainContext c,String source,String target,String kind){return link(c,source,target,kind,null);}
 private String link(DomainContext c,String source,String target,String kind,String activityId){var link=new LinkedHashMap<String,Object>();link.put("organizationId",c.organizationId());link.put("ID",UUID.randomUUID().toString());link.put("sourceWorkId",source);if(activityId!=null)link.put("activityId",activityId);link.put("targetWorkId",target);link.put("kind",kind);link.put("createdAt",clock.instant());repository.insert("mulino.work.WorkLinks",link);return String.valueOf(link.get("ID"));}
 private boolean reachable(DomainContext c,String from,String target,Set<String> seen){if(from.equals(target))return true;if(!seen.add(from))return false;return repository.links(c).stream().filter(l->from.equals(l.get("sourceWorkId"))&&"DEPENDS_ON".equals(l.get("kind"))).anyMatch(l->reachable(c,String.valueOf(l.get("targetWorkId")),target,seen));}
 private void transition(DomainContext c,Map<String,Object> w,String op,String previous,String reason){var r=new LinkedHashMap<String,Object>();r.put("organizationId",c.organizationId());r.put("ID",UUID.randomUUID().toString());r.put("workId",w.get("ID"));r.put("revision",w.get("revision"));r.put("operation",op);r.put("previousState",previous);r.put("state",w.get("status"));r.put("actorId",c.actorId());r.put("reason",reason);r.put("recordedAt",clock.instant());r.put("snapshotJson",encode(TransportValues.normalize(w)));repository.insert("mulino.work.WorkTransitions",r);repository.observed(c,w);}
 private Map<String,Object> row(DomainContext c,String id){var r=new LinkedHashMap<String,Object>();r.put("organizationId",c.organizationId());r.put("ID",id);r.put("revision",0);r.put("createdAt",clock.instant());r.put("recordedAt",clock.instant());r.put("effectiveAt",clock.instant());return r;}
 private void human(DomainContext c,String id){var actor=identities.actor(c.organizationId(),id).orElseThrow(DomainError::forbidden);if(!"HUMAN".equals(actor.get("kind")))throw DomainError.invalid("Current human responsibility required");
  Instant now=clock.instant();boolean current=identities.rows("Memberships",c.organizationId()).stream().anyMatch(m->id.equals(m.get("actorId"))&&m.get("revokedAt")==null&&!now.isBefore(Instant.parse(String.valueOf(m.get("validFrom"))))&&(m.get("validUntil")==null||now.isBefore(Instant.parse(String.valueOf(m.get("validUntil"))))));if(!current)throw DomainError.invalid("Current owner membership required");}
 private WorkAssessmentGuard guard(){var guard=assessments.getIfAvailable();if(guard==null)throw DomainError.unsupported();return guard;}
 private WorkResponsibility duties(){var duties=responsibility.getIfAvailable();if(duties==null)throw DomainError.unsupported();return duties;}
 private void state(String state,String required){if(!state.equals(required))throw DomainError.invalid("Invalid lifecycle transition");}
 private Map<String,Object> result(String id,String goal,int revision,String outcome){return Map.of("outcome",outcome,"revision",revision,"effects",Map.of("workId",id,"goalVersionId",goal),"workId",id,"goalVersionId",goal,"id",id,"quantityEffects",List.of());}
 private String operation(Map<String,Object> intent){return GoalInput.text(intent,"capabilityId");}
 private Map<String,Object> parameters(DomainContext c,Map<String,Object> intent){var slots=map(intent.get("slots"));var result=new LinkedHashMap<String,Object>();slots.forEach((k,v)->{if(v instanceof Map<?,?> typed&&typed.containsKey("value")&&typed.containsKey("type"))result.put(k,typed.get("value"));else if(v instanceof Map<?,?> reference&&reference.containsKey("type")&&reference.containsKey("id"))result.put(k,reference.get("id"));else result.put(k,v);});
  String op=operation(intent);
  if(op.equals("createWorkLink")){
    if(result.containsKey("sourceWorkId"))result.put("workId",result.remove("sourceWorkId"));
    if(result.containsKey("linkKind"))result.put("kind",result.remove("linkKind"));if(result.containsKey("activityId")){var activity=repository.activity(c,id(result,"activityId"),id(result,"occurrenceId"));Object source=activity.get("workId")==null?result.get("targetWorkId"):activity.get("workId");if(result.containsKey("workId")&&!Objects.equals(result.get("workId"),source))throw DomainError.invalid("Declared source Work differs from authoritative activity Work");result.put("workId",source);}
    if(result.containsKey("quantity")){var q=map(result.remove("quantity"));if(!q.keySet().equals(Set.of("value","unit")))throw DomainError.invalid("Typed contribution quantity required");result.put("quantityValue",q.get("value"));result.put("quantityUnit",q.get("unit"));}
    if(result.containsKey("physicalScope"))throw new DomainError("NEEDS_INPUT","VERIFIED_RANGE_REQUIRED","Free physical scope text cannot prove a disjoint contribution range; provide startQuantity");
  }
  if(op.equals("reviseGoal")&&result.containsKey("newDueAt")){
    if(!Set.of("workId","newDueAt","reason","previousGoalVersion").containsAll(result.keySet()))throw DomainError.invalid("Unsupported goal revision slot");
    var previous=repository.currentGoal(c,id(result,"workId"));Object version=result.remove("previousGoalVersion");
    if(!(version instanceof Number n)||n.intValue()!=((Number)previous.get("goalVersion")).intValue()||n.doubleValue()!=n.intValue())throw new DomainError("CONFLICT","GOAL_VERSION_CONFLICT","Previous goal version changed");
    var revised=new LinkedHashMap<String,Object>(decode(previous.get("slotsJson")));revised.put("dueAt",result.remove("newDueAt"));result.put("goal",revised);
  }
  if((op.equals("createWork")||op.equals("createDraft"))&&!result.containsKey("goal"))return publicDraft(c,intent,result);
  return result;}
 @SuppressWarnings("unchecked") private Map<String,Object> map(Object o){if(!(o instanceof Map))throw DomainError.invalid("Object slots required");return (Map<String,Object>)o;}
 private String id(Map<String,Object> p,String key){String s=GoalInput.text(p,key);try{UUID.fromString(s);}catch(Exception e){throw DomainError.invalid("UUID required for "+key);}return s;}
 private void activateCreated(DomainContext c,String id){var w=repository.require(c,id,true);var goal=repository.currentGoal(c,id);GoalInput.validate(decode(goal.get("slotsJson")),true);guard().requireSupportedGoal(c,goal);duties().activated(c,w,goal);repository.update(c,id,Map.of("status","ACTIVE","revision",1,"recordedAt",clock.instant(),"effectiveAt",clock.instant()));w.put("status","ACTIVE");w.put("revision",1);w.put("recordedAt",clock.instant());w.put("effectiveAt",clock.instant());transition(c,w,"activateWork","DRAFT",null);}
 private Map<String,Object> publicDraft(DomainContext c,Map<String,Object> intent,Map<String,Object> slots){
  if(!Set.of("workType","quantity","destinationId","dueAt","endpoint","quantityMode","period","eventKinds","distinctContributionScope","evidencePolicyVersion","evaluationTime","placeId","eligibilityAction","includeReservations","ownerId","supervisorId","timezone","observationPolicy","conditions","evaluatorVersion","lotId","originalText").containsAll(slots.keySet()))throw DomainError.invalid("Unsupported Work goal slot");
  var p=new LinkedHashMap<String,Object>();String item=null;if(intent.get("subjectRefs") instanceof List<?> refs)for(Object raw:refs){var ref=map(raw);if(Set.of("TradeItem","ITEM").contains(ref.get("type"))){if(item!=null)throw DomainError.invalid("Exactly one Work item required");item=String.valueOf(ref.get("id"));}}if(item==null)throw new DomainError("NEEDS_INPUT","ITEM_MISSING","Work item required");p.put("itemId",item);p.put("definitionVersionId",repository.definitionId(c,String.valueOf(intent.get("definitionVersion"))));p.put("kind",slots.getOrDefault("workType","FOLLOWUP"));for(String k:List.of("ownerId","supervisorId","lotId","originalText"))if(slots.containsKey(k))p.put(k,slots.get(k));if(intent.containsKey("conversationRequestId"))p.put("conversationRequestId",intent.get("conversationRequestId"));var g=new LinkedHashMap<String,Object>();for(String k:List.of("dueAt","endpoint","quantityMode","evidencePolicyVersion","timezone","observationPolicy","conditions","evaluatorVersion"))if(slots.containsKey(k))g.put(k,slots.get(k));var pinned=definitions.get(c.organizationId(),String.valueOf(p.get("definitionVersionId")));var provenance=new LinkedHashMap<String,Object>(map(intent.getOrDefault("provenance",Map.of())));var defaults=new LinkedHashMap<String,Object>();defaults.put("definitionVersionId",pinned.id());defaults.put("definitionContentHash",pinned.contentHash());if(!g.containsKey("evaluatorVersion")){g.put("evaluatorVersion",pinned.evaluatorVersion());provenance.put("evaluatorVersion","CONTEXT");}if(!g.containsKey("conditions")){var templates=pinned.goals().stream().filter(t->Objects.equals(t.endpoint(),g.get("endpoint"))&&Objects.equals(t.quantityMode(),g.get("quantityMode"))).toList();if(templates.size()==1){g.put("conditions",List.of(Map.of("id",templates.getFirst().name())));provenance.put("conditions","CONTEXT");}}if(!g.containsKey("timezone")){var contextPolicies=policies.current(c.organizationId(),"GOAL_CONTEXT",clock.instant());if(contextPolicies.size()==1){var policy=contextPolicies.getFirst();if(!Objects.equals(policy.get("contentHash"),DefinitionRepository.sha256(String.valueOf(policy.get("content")))))throw new DomainError("HELD","POLICY_HASH_MISMATCH","Goal context policy content does not match its immutable hash");var content=decode(policy.get("content"));if(content.get("timezone") instanceof String zone){g.put("timezone",zone);provenance.put("timezone","CONTEXT");defaults.put("timezonePolicyId",policy.get("ID"));defaults.put("timezonePolicyVersion",policy.get("version"));defaults.put("timezonePolicyHash",policy.get("contentHash"));}}}g.put("defaultContext",defaults);g.put("scope",Map.of("itemId",item));g.put("provenance",provenance);if(slots.containsKey("quantity")){var q=map(slots.get("quantity"));if(!Set.of("value","unit","provenance").containsAll(q.keySet()))throw DomainError.invalid("Invalid quantity");g.put("targetQuantity",q.get("value"));g.put("unit",q.get("unit"));}if(slots.containsKey("period")){var period=map(slots.get("period"));if(!Set.of("start","end","startInclusive","endInclusive").containsAll(period.keySet()))throw DomainError.invalid("Invalid goal period");if(period.containsKey("start"))g.put("periodStart",period.get("start"));if(period.containsKey("end"))g.put("periodEnd",period.get("end"));if(period.containsKey("startInclusive"))g.put("periodStartInclusive",period.get("startInclusive"));if(period.containsKey("endInclusive"))g.put("periodEndInclusive",period.get("endInclusive"));}if(slots.get("eventKinds") instanceof List<?> events){if(events.size()!=1||!(events.getFirst() instanceof String))throw DomainError.invalid("One explicit event kind required");g.put("eventKind",events.getFirst());}if(slots.containsKey("distinctContributionScope")){g.put("contributionScope",slots.get("distinctContributionScope"));g.put("deduplication","CANONICAL_OCCURRENCE");}if(slots.containsKey("evaluationTime"))g.put("evaluationAt",slots.get("evaluationTime"));if(slots.containsKey("placeId"))g.put("placeId",slots.get("placeId"));else if(slots.containsKey("destinationId"))g.put("placeId",slots.get("destinationId"));if(slots.containsKey("eligibilityAction"))g.put("action",slots.get("eligibilityAction"));if(slots.containsKey("includeReservations"))g.put("includeReserved",slots.get("includeReservations"));p.put("goal",g);return p;
 }
 private String encode(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw DomainError.invalid("Invalid goal JSON");}}
 private Map<String,Object> decode(Object o){try{return json.readValue(String.valueOf(o),Map.class);}catch(Exception e){throw DomainError.invalid("Missing stored goal inputs");}}
 private void validateKeys(String op,Map<String,Object> p){Set<String> keys=switch(op){case "createWork","createDraft"->Set.of("itemId","lotId","definitionVersionId","kind","ownerId","supervisorId","goal","conversationRequestId","originalText");case "waitWork"->Set.of("workId","wait");case "resumeWork"->Set.of("workId","evidence");case "reviseGoal"->Set.of("workId","goal","reason");case "closeWork","cancelDraft"->Set.of("workId","reason");case "createFollowup"->Set.of("workId","draft","reason","obligationIds");case "createWorkLink"->Set.of("workId","targetWorkId","kind","occurrenceId","quantityValue","quantityUnit","startQuantity","conditionId","activityId");default->Set.of("workId");};if(!keys.containsAll(p.keySet()))throw DomainError.invalid("Unsupported lifecycle slot");}
}
